/**
 * TEST-ONLY mock of @minecraft/server.
 *
 * Added Project Prompt 19 to unlock testing the EXECUTION-side classes
 * (builder/strategies/*.js, builder/TunnelExcavator.js,
 * builder/BridgeSupportBuilder.js, core/CancellationWatcher.js,
 * inventory/InventoryManager.js, inventory/ResourceValidator.js) — Project
 * Prompt 18's test harness could only reach planning-side code (terrain/*.js,
 * config/*.js) because every one of those files imports this real package,
 * which doesn't exist outside a running Minecraft world. This mock supplies
 * just enough of the real API's SHAPE for those files' own logic to run
 * against, in plain Node.
 *
 * NEVER bundled into the shipped .mcaddon — only `BP/`/`RP/` are packaged;
 * this lives at the repository root's `node_modules/`, which the addon
 * packaging step never touches. See tests/README.md.
 *
 * WHAT'S DELIBERATELY NOT HERE
 *   No attempt to replicate real Bedrock semantics beyond what this
 *   project's own code actually calls (confirmed by grepping every
 *   `@minecraft/server` import across `BP/scripts/`) — this is a shape-only
 *   mock for exercising THIS project's logic, not a general-purpose
 *   Minecraft simulator.
 */

export const GameMode = Object.freeze({
  Survival: "Survival",
  Creative: "Creative",
  Adventure: "Adventure",
  Spectator: "Spectator",
});

export const EquipmentSlot = Object.freeze({
  Mainhand: "Mainhand",
  Offhand: "Offhand",
  Head: "Head",
  Chest: "Chest",
  Legs: "Legs",
  Feet: "Feet",
});

/**
 * `BlockPermutation.resolve(typeId, states)` — every real call site in this
 * project either uses the returned object's `.typeId`/states purely to hand
 * to `block.setPermutation()` (which our mock Block, in tests/mockWorld.mjs,
 * reads back), or (InventoryManager.scanPlaceableMaterials) relies on this
 * throwing for a typeId that "isn't a valid block." This mock throws for a
 * small denylist of known non-block item IDs (mirroring what a real
 * placeable-probe test needs) and otherwise succeeds, matching the real API's
 * observed behavior this project already depends on (see InventoryManager.js's
 * own doc).
 */
const KNOWN_NON_BLOCK_ITEM_IDS = new Set([
  "minecraft:stick",
  "minecraft:diamond",
  "minecraft:apple",
  "minecraft:iron_ingot",
]);

/** v2.0.0: minimal ItemStack (InventoryManager.giveItems). */
export class ItemStack {
  constructor(typeId, amount = 1) {
    this.typeId = typeId;
    this.amount = amount;
    this.maxAmount = 64;
  }
}

export class BlockPermutation {
  constructor(typeId, states) {
    this.typeId = typeId;
    this.states = states ?? {};
  }

  getState(key) {
    return this.states[key];
  }

  static resolve(typeId, states) {
    if (KNOWN_NON_BLOCK_ITEM_IDS.has(typeId)) {
      throw new Error(`BlockPermutation.resolve: "${typeId}" is not a valid block (mock).`);
    }
    return new BlockPermutation(typeId, states);
  }
}

/**
 * `system.runJob(generator)` schedules a generator to run to completion
 * across real ticks. This mock has no tick concept — it drains the
 * generator to completion synchronously (a microtask queue would be more
 * faithful to "spread across time," but nothing this project's tests need
 * depends on genuine multi-tick pacing, only on the generator eventually
 * completing and its yields/return value being handled correctly).
 */
export const system = {
  runJob(generator) {
    let result = generator.next();
    while (!result.done) {
      result = generator.next();
    }
    return { cancel() {} };
  },
  /**
   * `system.run(callback)` defers `callback` to the next tick. This mock
   * queues it instead; tests drain the queue with the TEST-ONLY
   * `flushRunQueue()` below (added v2.0.0 for tests/interactionGate.test.mjs).
   */
  run(callback) {
    this._runQueue.push(callback);
    return this._runQueue.length;
  },
  /** TEST-ONLY: callbacks passed to `run()` that haven't been flushed yet. Not part of the real API. */
  _runQueue: [],
  /** TEST-ONLY: runs and clears every queued `run()` callback. Not part of the real API. */
  flushRunQueue() {
    const queued = this._runQueue.splice(0);
    for (const callback of queued) callback();
    return queued.length;
  },
};

function createEventSignal() {
  const handlers = [];
  return {
    subscribe(handler) {
      handlers.push(handler);
      return handler;
    },
    unsubscribe(handler) {
      const index = handlers.indexOf(handler);
      if (index !== -1) handlers.splice(index, 1);
    },
    /** TEST-ONLY convenience: fires every subscribed handler with `eventData`. Not part of the real API. */
    emit(eventData) {
      for (const handler of handlers.slice()) handler(eventData);
    },
  };
}

export const world = {
  beforeEvents: {
    playerLeave: createEventSignal(),
    playerInteractWithBlock: createEventSignal(), // v2.0.0 — lets tests import main.js and fire rail interactions
  },
  afterEvents: {
    playerDimensionChange: createEventSignal(),
    entityDie: createEventSignal(),
    playerGameModeChange: createEventSignal(),
  },
};
